The solution involves creating a custom React hook for image conversion:


```typescript
import { useState } from 'react';
import heic2any from 'heic2any';

const CONVERTED_IMAGE_TYPE = 'image/jpeg';
const CONVERTED_IMAGE_QUALITY = 0.9;

export const useImageConversion = () => {
  const [isConverting, setIsConverting] = useState(false);

  const convertHeic = async (file: File): Promise<File> => {
    if (!file.type.includes('heic') && !file.type.includes('heif')) {
      return file;
    }

    try {
      const convertedBlob = await heic2any({
        blob: file,
        toType: CONVERTED_IMAGE_TYPE,
        quality: CONVERTED_IMAGE_QUALITY,
      });
      // ... conversion logic
    } catch (error) {
      // ... handling error
    }
  };

  const convertImages = async (files: File[]) => {
    setIsConverting(true);
    try {
      // ... batch conversion logic with "convertHeic"
    } catch {
      // ... handling error
    } finally {
      setIsConverting(false);
    }
  };

  return { convertImages, isConverting };
};
```


Usage Example:


```typescript
const { convertImages } = useImageConversion();

const handleImageChange = async ({ file }) => {
  if (!file) return;

  try {
    const [convertedImage] = await convertImages([file]);
    // ... handle converted image
  } catch (error) {
    // ... error handling
  }
};
```

